parameters.text:
=Customer Request:
{{ $json.customer_request }}

Support Router Result:
{{ $json.router_result }}

Knowledge Agent Results:
{{ $json.knowledge_results }}

Proposed Response:
{{ $json.proposed_response }}

Response Metadata:
{{ $json.response_metadata }}

Conversation Context:
{{ $json.conversation_context }}

Validate the proposed response against the customer request, router result, knowledge results, metadata, and conversation context.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "is_valid": {
      "type": "boolean",
      "description": "Whether the proposed response is accurate, relevant, and sufficiently supported by the available information."
    },
    "decision": {
      "type": "string",
      "enum": ["send", "escalate"],
      "description": "Whether the proposed response can be sent to the customer or the case should be escalated."
    },
    "reason": {
      "type": "string",
      "description": "Concise explanation supporting the validation decision."
    }
  },
  "required": [
    "is_valid",
    "decision",
    "reason"
  ]
}
